={
  "model": "qwen2.5:7b-instruct-q4_K_M",
  "messages": [
    {
      "role": "system",
      "content": "You are a TypeScript expert. Generate a component contract interface. Include JSDoc comments, props with types, variants. Return ONLY valid TypeScript code, no markdown."
    },
    {
      "role": "user",
      "content": "Component: {{ $json.artifact_data.name }}\nDependencies: {{ JSON.stringify($json.artifact_data.dependencies) }}\n\nGenerate TypeScript interface for this component."
    }
  ],
  "temperature": 0.2
}

parameters.functionCode:
const response = $json.choices[0].message.content;
const componentName = $('Split Components').item.json.artifact_data.name;

// Extract TypeScript code
let code = response.match(/```typescript\n([\s\S]*?)\n```/)?.[1] || 
           response.match(/```\n([\s\S]*?)\n```/)?.[1] ||
           response;

return {
  json: {
    componentName,
    contractCode: code.trim(),
    filePath: `packages/shared-components/contracts/${componentName}.ts`
  }
};

const contracts = $input.all().map(item => item.json);

return {
  json: {
    contracts,
    contractCount: contracts.length,
    tokens: {
      colors: {
        primary: '#007AFF',
        secondary: '#5856D6',
        success: '#34C759',
        error: '#FF3B30'
      },
      spacing: { xs: 4, sm: 8, md: 16, lg: 24, xl: 32 },
      typography: {
        h1: { fontSize: 32, fontWeight: '700' },
        h2: { fontSize: 24, fontWeight: '600' },
        body: { fontSize: 16, fontWeight: '400' }
      }
    }
  }
};
